-- 8. 购物车 5 条测试数据（演示账号 verify_user_289，name/image/price/stock 从 product 表拷贝）
INSERT INTO cart_item (user_id, product_id, name, image, price, quantity, stock, create_time, update_time)
SELECT 1, p.id, p.name, p.image, p.price, t.qty, p.stock, NOW(), NOW()
FROM (SELECT 7 AS id, 2 AS qty UNION ALL SELECT 1, 1 UNION ALL SELECT 17, 1 UNION ALL SELECT 21, 3 UNION ALL SELECT 27, 2) t
INNER JOIN product p ON p.id = t.id;

-- 9. 商品销量与 order_item 聚合完全对齐（sales = 该商品全部明细数量之和）
UPDATE product p SET p.sales = (
  SELECT COALESCE(SUM(oi.quantity), 0) FROM order_item oi WHERE oi.product_id = p.id
);

-- 10. 修复原有 5 笔历史订单：明细价格补齐（price=0 → 商品现价），重算 total_amount/total_quantity
UPDATE order_item oi INNER JOIN product p ON oi.product_id = p.id
SET oi.price = p.price
WHERE oi.price = 0;
UPDATE `order` o SET
  o.total_amount = (SELECT COALESCE(SUM(oi.price * oi.quantity), 0) FROM order_item oi WHERE oi.order_id = o.id),
  o.total_quantity = (SELECT COALESCE(SUM(oi.quantity), 0) FROM order_item oi WHERE oi.order_id = o.id)
WHERE o.id <= 5;

SET FOREIGN_KEY_CHECKS = 1;

